import whisper
import json
import os
import re

FILLER_WORDS = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "well", "okay",
    "basically"
}

FILLER_PHRASES = [
    "you know",
    "i mean",
    "kind of",
    "i guess"
]

def clean_word(word):
    return re.sub(r'[^\w\s]', '', word.lower()).strip()

def detect_fillers(video_path, output_json):
    print(f"Loading Whisper model...")
    model = whisper.load_model("tiny")

    print(f"Transcribing {video_path}...")
    result = model.transcribe(video_path, word_timestamps=True, language="en")

    all_words = []
    for segment in result["segments"]:
        for word_info in segment.get("words", []):
            all_words.append({
                "word": word_info["word"].strip(),
                "start": word_info["start"],
                "end": word_info["end"]
            })

    detected = []

    # Track which indices are already used by phrases to avoid double counting
    used_indices = set()

    # 1. Detect Phrases
    for phrase in FILLER_PHRASES:
        phrase_words = phrase.lower().split()
        phrase_len = len(phrase_words)

        for i in range(len(all_words) - phrase_len + 1):
            if i in used_indices:
                continue

            match = True
            for j in range(phrase_len):
                if clean_word(all_words[i+j]["word"]) != phrase_words[j]:
                    match = False
                    break

            if match:
                detected.append({
                    "word": phrase,
                    "timestamp": round(all_words[i]["start"], 2)
                })
                for j in range(phrase_len):
                    used_indices.add(i + j)

    # 2. Detect Single Words
    for i, word_info in enumerate(all_words):
        if i in used_indices:
            continue

        word = clean_word(word_info["word"])
        if word in FILLER_WORDS:
            detected.append({
                "word": word,
                "timestamp": round(word_info["start"], 2)
            })
            used_indices.add(i)

    # Sort by timestamp
    detected.sort(key=lambda x: x["timestamp"])

    print(f"Detected {len(detected)} filler words/phrases.")

    with open(output_json, "w") as f:
        json.dump(detected, f, indent=2)

    return detected

if __name__ == "__main__":
    detect_fillers("/root/input.mp4", "/root/annotations.json")

